// Add a function to String
fun String.isPalindrome(): Boolean {
    val cleaned = this.lowercase().filter { it.isLetter() }
    return cleaned == cleaned.reversed()
}

// Usage — reads like a built-in method
"racecar".isPalindrome()  // true
"hello".isPalindrome()    // false

class HtmlBuilder {
    private val out = StringBuilder()

    // extension on String, usable only inside HtmlBuilder
    private fun String.bold() = "<b>$this</b>"

    fun paragraph(text: String) {
        out.append("<p>${text.bold()}</p>")
    }
}

// "x".bold()  // does not compile outside HtmlBuilder

fun <T : Comparable<T>> List<T>.isSorted(): Boolean =
    zipWithNext().all { (a, b) -> a <= b }

listOf(1, 2, 3).isSorted()        // true
// listOf(Any(), Any()).isSorted() // does not compile

inline fun <reified T> Iterable<*>.firstOfType(): T? =
    filterIsInstance<T>().firstOrNull()

